/*!
 * Freshdesk Messaging Facade v1.3.2 (https://github.com/coliff/freshdesk-messaging-facade)
 */
class FreshchatFacade extends HTMLElement{connectedCallback(){this.removeAttribute("hidden");this.siteId=this.getAttribute("data-siteid");this.token=this.getAttribute("data-token");this.host=this.getAttribute("data-host")||"https://wchat.freshchat.com";const load=()=>{FreshchatFacade.warmConnections(this.host);this.addScript()};this.addEventListener("pointerover",load,{once:true});this.addEventListener("focusin",load,{once:true})}static addPrefetch(kind,url,as){const linkEl=document.createElement("link");linkEl.rel=kind;linkEl.href=url;if(as){linkEl.as=as}document.head.append(linkEl)}static warmConnections(host){if(FreshchatFacade.preconnected){return}FreshchatFacade.addPrefetch("preconnect",host);FreshchatFacade.addPrefetch("preconnect","https://assetscdn-wchat.freshchat.com");FreshchatFacade.preconnected=true}addScript(){if(this.scriptAdded){return}this.scriptAdded=true;const icon=this.querySelector("#freshdesk-messaging-icon");if(icon){icon.classList.add("freshdesk-messaging-icon-loading")}const script=document.createElement("script");script.src=`${this.host}/js/widget.js`;script.onerror=()=>{this.setAttribute("hidden","hidden")};script.onload=()=>{fcWidget.init({token:this.token,host:this.host,siteId:this.siteId,config:{headerProperty:{hideChatButton:false}}});fcWidget.on("widget:opened",()=>{this.setAttribute("hidden","hidden")})};document.head.append(script)}}customElements.define("freshdesk-messaging-facade",FreshchatFacade);